import { useEffect, useRef, useState } from "react";
import { AiOutlineDown } from "react-icons/ai";
import CourseSubSectionAccordion from "./CourseSubSectionAccordion";

export default function CourseAccordionBar({ course, isActive = [], handleActive }) {
  const contentEl = useRef(null);
  const [active, setActive] = useState(false);
  const [sectionHeight, setSectionHeight] = useState(0);

  // Safe defaults if course is undefined
  const safeCourse = course || {
    _id: '',
    sectionName: 'Untitled Section',
    subSection: []
  };

  // Check if current course is active
  useEffect(() => {
    setActive(isActive.includes(safeCourse._id));
  }, [isActive, safeCourse._id]);

  // Calculate section height when active state changes
  useEffect(() => {
    if (!contentEl.current) return;
    setSectionHeight(active ? contentEl.current.scrollHeight : 0);
  }, [active]);

  // Early return if course data is invalid
  if (!course) {
    return (
      <div className="border border-solid border-richblack-600 bg-richblack-700 p-4 text-richblack-5">
        <p>Section data not available</p>
      </div>
    );
  }

  return (
    <div className="overflow-hidden border border-solid border-richblack-600 bg-richblack-700 text-richblack-5 last:mb-0">
      <div>
        <div
          className={`flex cursor-pointer items-start justify-between bg-opacity-20 px-7 py-6 transition-[0.3s]`}
          onClick={() => handleActive(safeCourse._id)}
        >
          <div className="flex items-center gap-2">
            <i className={active ? "rotate-180" : "rotate-0"}>
              <AiOutlineDown />
            </i>
            <p>{safeCourse.sectionName}</p>
          </div>
          <div className="space-x-4">
            <span className="text-yellow-25">
              {`${safeCourse.subSection?.length || 0} lecture(s)`}
            </span>
          </div>
        </div>
      </div>
      <div
        ref={contentEl}
        className={`relative overflow-hidden bg-richblack-900 transition-[height] duration-[0.35s] ease-[ease]`}
        style={{ height: `${sectionHeight}px` }}
      >
        <div className="text-textHead flex flex-col gap-2 px-7 py-6 font-semibold">
          {safeCourse.subSection?.map((subSec, i) => (
            <CourseSubSectionAccordion 
              subSec={subSec} 
              key={subSec._id || i} 
            />
          ))}
        </div>
      </div>
    </div>
  );
}
